__attribute__((noinline))
static unsigned long long fn_1(unsigned long long x, unsigned long long y, int arg) {
    return (x ^ (y >> (arg & 31))) * 5ull + (unsigned long long)arg;
}

__attribute__((noinline))
static unsigned long long fn_7(unsigned long long x, unsigned long long y, int arg) {
    return (x ^ (y >> (arg & 31))) * 17ull + (unsigned long long)arg;
}

__attribute__((noinline))
static void note(struct exprstate *state, int at, unsigned long long value) {
    state->out[at] = state->out[at] * 5ull + value;
}

