static unsigned long long run(
    unsigned long long (*interp)(struct step *, struct exprstate *),
    unsigned long long seed, unsigned int loops) {
    struct exprstate state;
    state.seed = seed;
    state.loops = loops;
    for (int i = 0; i < 8; i++) {
        state.out[i] = (unsigned long long)i;
    }
    unsigned long long h = interp(steps, &state);
    for (int i = 0; i < 8; i++) {
        h = h * 31ull + state.out[i];
    }
    return h;
}
